<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import InputError from '@/Components/InputError.vue';
import ValidationSummary from '@/Components/ValidationSummary.vue';
import Badge from '@/Components/UI/Badge.vue';
import Button from '@/Components/UI/Button.vue';
import Card from '@/Components/UI/Card.vue';
import EmptyState from '@/Components/UI/EmptyState.vue';
import PageHeader from '@/Components/UI/PageHeader.vue';
import Pagination from '@/Components/UI/Pagination.vue';
import { date, money, paymentStatus, statusTone } from '@/Support/AdminPresentation';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { computed, reactive, watch } from 'vue';

const props = defineProps<{ payments: any[]; summary: any; customers: any[]; events: any[]; coupons: any[]; filters: any; pagination?: any }>();
const filters = reactive({ ...props.filters });
const form = useForm({ customer_id: '', event_id: '', event_package_id: '', original_amount: '', coupon_id: '', discount_type: '', discount_value: '', paid_amount: '', payment_method: 'cash', reference: '', payment_date: '', notes: '' });
const selectedCustomerEvents = computed(() => props.events.filter((event) => String(event.customer_id) === String(form.customer_id)));
const selectedEvent = computed(() => selectedCustomerEvents.value.find((event) => String(event.id) === String(form.event_id)));
const selectedCoupon = computed(() => props.coupons.find((coupon) => String(coupon.id) === String(form.coupon_id)));
const preview = computed(() => { const original = Math.max(Number(form.original_amount) || 0, 0); const type = selectedCoupon.value?.discount_type || form.discount_type; const value = Number(selectedCoupon.value?.discount_value ?? form.discount_value) || 0; const discount = Math.min(original, type === 'percentage' ? original * value / 100 : type === 'fixed' ? value : 0); return { original, discount, final: Math.max(original - discount, 0) }; });
const apply = () => router.get(route('admin.payments.index'), filters, { preserveState: true, replace: true });
const reset = () => { filters.search = ''; filters.status = ''; filters.customer_id = ''; apply(); };
watch(() => form.customer_id, () => { form.event_id = ''; form.event_package_id = ''; form.original_amount = ''; });
watch(selectedEvent, (event) => { form.event_package_id = event?.event_package_id || ''; form.original_amount = event?.package?.price ?? ''; });
const chooseCoupon = () => { if (form.coupon_id) { form.discount_type = ''; form.discount_value = ''; } };
const chooseDiscount = () => { if (form.discount_type || form.discount_value !== '') form.coupon_id = ''; };
</script>

<template>
    <Head title="Payments" />
    <AuthenticatedLayout>
        <template #header><PageHeader title="Payments" subtitle="Track client obligations, collected payments, and balances." /></template>
        <div class="fe-page fe-page-wide space-y-6">
            <section class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><Card><p class="text-sm text-[color:var(--fe-text-muted)]">Final obligations</p><p class="mt-2 text-2xl font-semibold">{{ money(summary.total_final_amount) }}</p></Card><Card><p class="text-sm text-[color:var(--fe-text-muted)]">Collected</p><p class="mt-2 text-2xl font-semibold">{{ money(summary.total_paid_amount) }}</p></Card><Card><p class="text-sm text-[color:var(--fe-text-muted)]">Outstanding</p><p class="mt-2 text-2xl font-semibold">{{ money(summary.total_remaining_amount) }}</p></Card></section>

            <Card><form class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3" @submit.prevent="form.post(route('admin.payments.store'))"><div class="sm:col-span-2 lg:col-span-3"><h2 class="fe-section-title">Create Financial Record</h2><p class="fe-section-copy">Choose a client and event, then review the calculated original, discount, and final amounts.</p></div><label>Client<select v-model="form.customer_id" required class="mt-1 w-full"><option value="">Select client</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.name }}</option></select><InputError :message="form.errors.customer_id" class="mt-1" /></label><label>Event<select v-model="form.event_id" :disabled="!form.customer_id" class="mt-1 w-full"><option value="">No event</option><option v-for="event in selectedCustomerEvents" :key="event.id" :value="event.id">{{ event.title || 'Invitation setup' }}</option></select><InputError :message="form.errors.event_id" class="mt-1" /></label><div><span class="fe-form-label">Package</span><p class="mt-1 min-h-10 rounded border border-[color:var(--fe-border-strong)] bg-[color:var(--fe-surface-elevated)] px-3 py-2 text-sm">{{ selectedEvent ? (selectedEvent.package?.name || 'No package assigned') : 'Select an event' }}</p><input v-model="form.event_package_id" type="hidden" /></div><label>Original amount<input v-model="form.original_amount" type="number" min="0" step="0.01" required class="mt-1 w-full" /><InputError :message="form.errors.original_amount" class="mt-1" /></label><label>Coupon (optional)<select v-model="form.coupon_id" :disabled="!!form.discount_type || form.discount_value !== ''" class="mt-1 w-full" @change="chooseCoupon"><option value="">No coupon</option><option v-for="coupon in coupons" :key="coupon.id" :value="coupon.id">{{ coupon.code }}</option></select></label><label>Manual discount<select v-model="form.discount_type" :disabled="!!form.coupon_id" class="mt-1 w-full" @change="chooseDiscount"><option value="">No manual discount</option><option value="fixed">Fixed amount</option><option value="percentage">Percentage</option></select></label><label>Discount value<input v-model="form.discount_value" :disabled="!form.discount_type || !!form.coupon_id" type="number" min="0" step="0.01" class="mt-1 w-full" @input="chooseDiscount" /></label><div class="rounded border border-[color:var(--fe-border)] bg-[color:var(--fe-surface-elevated)] p-3 text-sm"><p class="font-semibold">Financial preview</p><dl class="mt-2 grid gap-1"><div class="flex justify-between"><dt>Original</dt><dd>{{ money(preview.original) }}</dd></div><div class="flex justify-between"><dt>Discount</dt><dd>{{ money(preview.discount) }}</dd></div><div class="flex justify-between font-semibold"><dt>Final</dt><dd>{{ money(preview.final) }}</dd></div></dl></div><label>Initial confirmed payment<input v-model="form.paid_amount" type="number" min="0" step="0.01" class="mt-1 w-full" /><InputError :message="form.errors.paid_amount" class="mt-1" /></label><label>Payment method<input v-model="form.payment_method" class="mt-1 w-full" /></label><label>Reference<input v-model="form.reference" class="mt-1 w-full" /></label><label>Payment date<input v-model="form.payment_date" type="date" class="mt-1 w-full" /></label><label>Notes<input v-model="form.notes" class="mt-1 w-full" /></label><div class="sm:col-span-2 lg:col-span-3"><ValidationSummary :errors="form.errors" /></div><Button type="submit" :loading="form.processing">Create Financial Record</Button></form></Card>

            <form class="fe-card fe-card-muted flex flex-wrap gap-2 p-3" @submit.prevent="apply"><input v-model="filters.search" placeholder="Search client, event, coupon, reference" class="w-full min-w-0 sm:w-auto sm:min-w-64" /><select v-model="filters.status" class="w-full min-w-0 sm:w-auto"><option value="">All payment statuses</option><option value="unpaid">Unpaid</option><option value="partially_paid">Partially Paid</option><option value="paid">Paid</option></select><select v-model="filters.customer_id" class="w-full min-w-0 sm:w-auto"><option value="">All clients</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{ customer.name }}</option></select><Button type="submit">Apply</Button><Button type="button" variant="ghost" @click="reset">Reset</Button></form>

            <div v-if="payments.length" class="space-y-4"><div class="fe-table-wrap"><table class="fe-table min-w-[54rem]"><thead><tr><th>Client / Event</th><th class="text-right">Final</th><th class="text-right">Paid</th><th class="text-right">Remaining</th><th>Status</th><th>Latest payment</th><th class="text-right">Action</th></tr></thead><tbody><tr v-for="payment in payments" :key="payment.id"><td><p class="font-semibold">{{ payment.customer?.name }}</p><p class="mt-1 text-xs text-[color:var(--fe-text-muted)]">{{ payment.event?.title || 'No event' }}</p></td><td class="text-right font-medium">{{ money(payment.final_amount) }}</td><td class="text-right">{{ money(payment.paid_amount) }}</td><td class="text-right">{{ money(Math.max(Number(payment.final_amount) - Number(payment.paid_amount), 0)) }}</td><td><Badge :tone="statusTone(payment.status)">{{ paymentStatus(payment.status) }}</Badge></td><td>{{ payment.latest_transaction?.payment_date ? date(payment.latest_transaction.payment_date) : 'No payment yet' }}</td><td class="text-right"><Link :href="route('admin.payments.show', payment.id)" class="fe-btn fe-btn-secondary">View</Link></td></tr></tbody></table></div><Pagination :pagination="pagination" /></div><EmptyState v-else title="No financial records match these filters." message="Create a financial record when a client obligation is ready to track." />
        </div>
    </AuthenticatedLayout>
</template>
